def current_time_with_seconds_zero_to_timestamp():
    ''' 获取当前时间时间戳并将秒数置0以便拿到整时整分0秒'''
    now = datetime.datetime.now()
    now_zero_seconds = now.replace(second=0, microsecond=0)
    timestamp = int(now_zero_seconds.timestamp())
    return timestamp

