    @allure.title("通知&获取表显续航里程_typeRangeIncrease_重启场景_参数和base均持久化")
    @pytest.mark.sanity
    def test_caseid_1989328(self):  
        data=self.return_carconfig_EnergyConsumptionData(ccp950=0x01, ccp3=0x80, ccp966=0x02, ccp566=0x18, ccp948=0x04) # CLTC=700, WLTP=588, EPA=599
        cltcFullRange, wltpFullRange, epaFullRange = data["cltcFullRange"], data["wltpFullRange"], data["epaFullRange"]    
        self.set_range(SOH=70.0, calculateDTESOC=40.0, maxSOC=100.0)
        # 拔枪清零 base=-1 ChargingInfo.isConnect=False ChargingInfo.isCharging=False 
        self.ipdu.set(self.ipdu.backbonefr.VddmBackBoneFr16, 'ChrgnOrDisChrgnStsFb', 0) # ChargingInfo.isCharging=False
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr15, 'DCChrgnHndlSts', 0) # ChargingInfo.isConnect=False
        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetChargingInfo", {}, {"out":{"isConnect":False, "isCharging":False}}, timeout=2)  
        self.partner.empty_all(2)
        # ChargingInfo.isCharging=True base=-1  更新base
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr15, 'DCChrgnHndlSts', 1) # ChargingInfo.isConnect=True
        self.ipdu.set(self.ipdu.backbonefr.VddmBackBoneFr16, 'ChrgnOrDisChrgnStsFb', 2) 
        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetChargingInfo", {}, {"out":{"isConnect":True, "isCharging":True}}, timeout=2)  
        base_TypeRange=self.calculate_TypeRange_or_targetTypeRange(70.0, SOC=40.0, typeFullRange=[cltcFullRange, wltpFullRange, epaFullRange])
        # 存在TyepRange
        self.set_range(SOH=70.0, calculateDTESOC=80.0, maxSOC=100.0)
        # sleep(2)
        # data=self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetRange", {})["out"]
        TypeRange=self.calculate_TypeRange_or_targetTypeRange(70.0, SOC=80.0, typeFullRange=[cltcFullRange, wltpFullRange, epaFullRange])
        self.partner.ck_event_and_resp(HIGHVOLTAGE_SERVICE_CLIENT, "NotifyRange", 
                                       {"infos": {"CLTCRangeIncrease": TypeRange["cltc"]-base_TypeRange["cltc"], 
                                                  "EPARangeIncrease": TypeRange["epa"]-base_TypeRange["epa"],
                                                  "WLTPRangeIncrease": TypeRange["wltp"]-base_TypeRange["wltp"]}})  
        sleep(2)
        self.restart_bgm_and_connect_service(HIGHVOLTAGE_SERVICE_CLIENT, pause_all_bus=True, resume_all_bus=False)
        self.partner.ck_event_and_resp(HIGHVOLTAGE_SERVICE_CLIENT, "NotifyRange", 
                                       {"infos": {"CLTCRangeIncrease": TypeRange["cltc"]-base_TypeRange["cltc"], 
                                                  "EPARangeIncrease": TypeRange["epa"]-base_TypeRange["epa"],
                                                  "WLTPRangeIncrease": TypeRange["wltp"]-base_TypeRange["wltp"]}}, timeout=5) # 此时CLTCRange应该为65535
        self.ipdu.resume_all_bus_send()
        self.partner.ck_event_and_resp(HIGHVOLTAGE_SERVICE_CLIENT, "NotifyRange", 
                                       {"infos": {"CLTCRangeIncrease": TypeRange["cltc"]-base_TypeRange["cltc"], 
                                                  "EPARangeIncrease": TypeRange["epa"]-base_TypeRange["epa"],
                                                  "WLTPRangeIncrease": TypeRange["wltp"]-base_TypeRange["wltp"]}}, timeout=5) # 总线恢复后也应该为last_value
        # 存在TyepRange base沿用记忆值
        self.set_range(SOH=70.0, calculateDTESOC=95.9, maxSOC=100.0) 
        TypeRange=self.calculate_TypeRange_or_targetTypeRange(70.0, SOC=95.9, typeFullRange=[cltcFullRange, wltpFullRange, epaFullRange])
        self.partner.ck_event_and_resp(HIGHVOLTAGE_SERVICE_CLIENT, "NotifyRange", 
                                       {"infos": {"CLTCRangeIncrease": TypeRange["cltc"]-base_TypeRange["cltc"], 
                                                  "EPARangeIncrease": TypeRange["epa"]-base_TypeRange["epa"],
                                                  "WLTPRangeIncrease": TypeRange["wltp"]-base_TypeRange["wltp"]}})  
        
