    @allure.title("通知&获取表显续航里程_typeRangeIncrease_重启场景_插枪充电下休眠_拔枪后唤醒_唤醒后继续充电")
    @pytest.mark.full
    def test_caseid_1989330(self):
        data=self.return_carconfig_EnergyConsumptionData(ccp950=0x02, ccp3=0x81, ccp966=0x02, ccp566=0x17, ccp948=0x04) # CLTC=660, WLTP=560, EPA=599
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr15, 'DCChrgnHndlSts', 1) # ChargingInfo.isConnect=True
        self.ipdu.set(self.ipdu.backbonefr.VddmBackBoneFr16, 'ChrgnOrDisChrgnStsFb', 2) 
        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetChargingInfo", {}, {"out":{"isConnect":True, "isCharging":True}}, timeout=2)  
        self.set_range(SOH=100.0, calculateDTESOC=30.1, maxSOC=100.0)
        sleep(2)
        self.ipdu.set(self.ipdu.backbonefr.VddmBackBoneFr16, 'ChrgnOrDisChrgnStsFb', 0) # ChargingInfo.isCharging=False
        data=self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetRange", {})["out"]
        sleep(2)
        self.nucapp.bgm_power_off() #下电
        sleep(3)
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr15, 'DCChrgnHndlSts', 0) #没插枪没充电
        self.nucapp.bgm_power_on()
        sleep(3)
        # 唤醒后 base=-1
        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetChargingInfo", {}, {"out":{"isConnect":False, "isCharging":False}}, timeout=5)
        self.partner.ck_event_and_resp(HIGHVOLTAGE_SERVICE_CLIENT, "NotifyRange", 
                                       {"infos": {"CLTCRangeIncrease": data["CLTCRangeIncrease"], 
                                                  "EPARangeIncrease": data["EPARangeIncrease"], 
                                                  "WLTPRangeIncrease": data["WLTPRangeIncrease"]}}) 
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr15, 'DCChrgnHndlSts', 1) # ChargingInfo.isConnect=True  
        self.partner.ck_event_and_resp(HIGHVOLTAGE_SERVICE_CLIENT, "NotifyRange", 
                                       {"infos": {"CLTCRangeIncrease": 0, "EPARangeIncrease": 0, "WLTPRangeIncrease": 0}}) 
        self.partner.empty_all(2)
        # 更新base
        self.set_range(SOH=100.0, calculateDTESOC=60.1, maxSOC=100.0)
        self.ipdu.set(self.ipdu.backbonefr.VddmBackBoneFr16, 'ChrgnOrDisChrgnStsFb', 2) 
        self.partner.ck_event_and_resp(HIGHVOLTAGE_SERVICE_CLIENT, "NotifyRange", 
                                       {"infos": {"CLTCRangeIncrease": 0, "EPARangeIncrease": 0, "WLTPRangeIncrease": 0}}) # 只要增量=0，就说明重新记了base
                    
