        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr15, 'DCChrgnHndlSts', 1) # ChargingInfo.isConnect=True
        sleep(2) # 此时baseSoc=0
        self.ipdu.set(self.ipdu.propulsioncan.EcmPropFr04, 'DispHvBattLvlOfChrg', 5.0) # HVSOCInfo.displaySoc=5
        sleep(1)
