    def set_default(self, HvBattUDc=400.0, HvBattChrgnPwrCns1=35000.0):
        '''电池充电慢提醒 前置使得 acuC按照信号赋值 '''
        self.sd_tester.write_single_ccp(962,0) # 400V
        self.sd_tester.write_single_ccp(973, 0) # 支持直流
        self.ipdu.set(self.ipdu.chassiscan1.EcmChas1Fr19, 'HvBattThermPwrCns', 0.0)
        self.ipdu.set(self.ipdu.chassiscan1.EcmChas1Fr41, 'HvCabinThermPwrCns', 0.0)
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr13, 'HvBattChrgnPwrCns1', 0)
        self.ipdu.set(self.ipdu.backbonefr.VddmBackBoneFr16, 'ChrgnOrDisChrgnStsFb', 0)
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr01, 'HvBattUDc', 0.0)
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr22, 'ChrgEquipIDc', 0.0)
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr15, 'DCChrgnHndlSts', 0)
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr15, 'HvBattIDc1', 0.0)
        sleep(2)
        self.restart_bgm_and_connect_service(HIGHVOLTAGE_SERVICE_CLIENT)
        sleep(2)
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr01, 'HvBattUDc', HvBattUDc)
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr13, 'HvBattChrgnPwrCns1', HvBattChrgnPwrCns1)
        sleep(5)
        
