    @allure.title("获取和通知电机信息_遍历所有信号")
    @pytest.mark.full
    def test_caseid_1943228(self):
        #电机数量
        self.sd_tester.write_multi_ccp({3: 129, 4: 6,950:1,962:0})
        sleep(3)
        self.restart_bgm_and_connect_service(HIGHVOLTAGE_SERVICE_CLIENT)
        sleep(1)
        self.ipdu.set(self.ipdu.propulsioncan.IemPropFr06, 'IemGenericEMQnty', 2)
        self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr07, 'IgmGenericEMSeqNr', 1)
        self.ipdu.set(self.ipdu.propulsioncan.IemPropFr06, 'IemGenericModStatusRms', 1)
        self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr06, 'IsgTqActQualityFactor', 3)
        self.ipdu.set(self.ipdu.propulsioncan.IemEduPropFr01, 'WhlMotSysTqEstQualityFactor',3)
        self.partner.empty_all(1)      
        def input(value):
            return True if input ==3 else False
        for number in range(1,16):
            logger.info(f"--IemGenericEMQnty发送{number}")
            self.ipdu.set(self.ipdu.propulsioncan.IemPropFr06, 'IemGenericEMQnty', number)
            sleep(0.5)
            self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr07, 'IgmGenericModStatusRms', number)
            sleep(0.5)
            self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "MotorInfo",{"motorNumber": number})
            self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr07, 'IgmGenericModStatusRms', 0)
            sleep(0.5)
        #前后电机序号&工作模式
        for index in range(1,16):
            logger.info(f"--序号和工作模式发送{index}")
            self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr07, 'IgmGenericModStatusRms', index)
            self.ipdu.set(self.ipdu.propulsioncan.IemPropFr06, 'IemGenericModStatusRms', index)
            sleep(0.5)
            self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "MotorInfo",
                                    {"motorNumber": 15, "motorsInfo": 
                                     [{"motorId": 0,"motorWorkingMode": index},
                                      {"motorId": 1,"motorWorkingMode": index}]})
            self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetMotorInfo", {"motors": [0,1]},
                                                    {"out": [{"motorId": 0, "motorWorkingMode": index},
                                                             {"motorId": 1, "motorWorkingMode": index}]})
        #前后电机温度&控制器温度
        for temp in [-50.0,100.0,200.0]:
            logger.info(f"--控制器温度和电机温度发送{temp}")
            self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr02, 'IsgInvrT', temp)
            self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr03, 'IsgMotT',temp)
            self.ipdu.set(self.ipdu.propulsioncan.IemPropFr03, 'WhlMotSysInvrT', temp)
            self.ipdu.set(self.ipdu.propulsioncan.IemPropFr03, 'WhlMotSysMotT',temp)
            sleep(0.5)
            self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "MotorInfo",
                                    {"motorNumber": 15, "motorsInfo": 
                                     [{"motorId": 0,"inverterTemperature": temp,"motorTemperature": temp},
                                      {"motorId": 1,"inverterTemperature": temp,"motorTemperature": temp}]})
            self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetMotorInfo", {"motors": [0,1]},
                                                    {"out": [{"motorId": 0,"inverterTemperature": temp,"motorTemperature": temp},
                                                             {"motorId": 1,"inverterTemperature": temp,"motorTemperature": temp}]})
        #前后电机扭矩QF
        for QF in range(3):
            logger.info(f"--QF发送{QF}")
            self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr06, 'IsgTqActQualityFactor', QF)
            self.ipdu.set(self.ipdu.propulsioncan.IemEduPropFr01, 'WhlMotSysTqEstQualityFactor',QF)
            sleep(0.5)
            self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "MotorInfo",
                                        {"motorNumber": 15, "motorsInfo": 
                                        [{"motorId": 0,"motorTorque":{"isValid": input(QF)}},{"motorId": 1,"motorTorque":{"isValid": input(QF)}}]})
            self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr06, 'IsgTqActQualityFactor', 3)
            self.ipdu.set(self.ipdu.propulsioncan.IemEduPropFr01, 'WhlMotSysTqEstQualityFactor',3)
            sleep(0.5)
            self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetMotorInfo", {"motors": [0,1]},
                                    {"out": [{"motorId": 0,"motorTorque":{"isValid": True}},{"motorId": 1,"motorTorque":{"isValid": True}}]})
        #前后电机电流
        for current in [-818.0,0.0,819.0]:
            logger.info(f"--电流发送{current}")
            self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr03, 'IsgIDc', current)
            self.ipdu.set(self.ipdu.propulsioncan.IemPropFr08, 'WhlMotSysIdc',current)
            sleep(0.5)
            self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "MotorInfo",
                                    {"motorNumber": 15, "motorsInfo": 
                                     [{"motorId": 0,"busbarCurrent": current},{"motorId": 1,"busbarCurrent": current}]})
            self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetMotorInfo", {"motors": [0,1]},
                                    {"out": [{"motorId": 0,"busbarCurrent": current},{"motorId": 1,"busbarCurrent": current}]})
        #前后电机冷却温度
        for motorCoolTemp in [-40.0,0.0,215.0]:
            logger.info(f"--冷却温度发送{motorCoolTemp}")
            self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr03, 'IsgCooltT', motorCoolTemp)
            self.ipdu.set(self.ipdu.propulsioncan.IemEduPropFr02, 'WhlMotSysCooltT',motorCoolTemp)
            sleep(0.5)
            self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "MotorInfo",
                                    {"motorNumber": 15, "motorsInfo": 
                                     [{"motorId": 0,"motorCoolTemp": motorCoolTemp},{"motorId": 1,"motorCoolTemp": motorCoolTemp}]})
            self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetMotorInfo", {"motors": [0,1]},
                                    {"out": [{"motorId": 0,"motorCoolTemp": motorCoolTemp},{"motorId": 1,"motorCoolTemp": motorCoolTemp}]})
    
