    def test_caseid_105838(self):
        def results (X, Y):
            return True if X ==1 or Y == 1 else False
        self.ipdu.set(self.ipdu.chassiscan2.EcmChas2Fr19, 'HybErrIndcnReqTelltlBattTracCutOff', 1)
        self.ipdu.set(self.ipdu.chassiscan2.EcmChas2Fr19, 'HybErrIndcnReqTelltlBattTracFailr', 1)
        self.partner.empty_all(1)
        for X1 in [0, 1]:
            self.ipdu.set(self.ipdu.chassiscan2.EcmChas2Fr19, 'HybErrIndcnReqTelltlBattTracCutOff', X1)
            sleep(1)
            for Y1 in [0, 1]:
                self.ipdu.set(self.ipdu.chassiscan2.EcmChas2Fr19, 'HybErrIndcnReqTelltlBattTracFailr', Y1)
                sleep(1)
                logger.info(f"-----发送TracCutOff{X1}----TracFailr{Y1}")
                self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "HVBatteryFault",
                                           {"state": results(X1, Y1)})
                self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, 
                                                      "GetHVBatteryFault", {}, {"out": results(X1, Y1)})
                self.ipdu.set(self.ipdu.chassiscan2.EcmChas2Fr19, 'HybErrIndcnReqTelltlBattTracCutOff', 0)
                self.ipdu.set(self.ipdu.chassiscan2.EcmChas2Fr19, 'HybErrIndcnReqTelltlBattTracFailr', 0)
                self.partner.empty_all(1.5) #本身周期就是1S，防止信号发不过去改为1.5S
        
