    @allure.title("通知和获取高压电池SOC状态_realSoc")
    @pytest.mark.sanity
    def test_caseid_1979692(self):
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr03,'HvBattSoc', 10.0)
        self.partner.empty_all(0.2) 
        # UB位=0且信号0时不触发event
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr03,'HvBattSoc', 0.0,ub_flag=False)
        sleep(1)
        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetHVSOCInfo", {},
                                                {'out': {'realSoc': 10.0}})
        #UB等于1但信号等于0
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr03,'HvBattSoc', 0.0,ub_flag=True)
        sleep(1)
        self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT,"HVSOCInfo",{"info":{"realSoc":0.0}})
        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetHVSOCInfo", {},
                                            {'out': {'realSoc': 0.0}})
        #UB等于0但信号不等于0
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr03,'HvBattSoc', 100.0,ub_flag=False)
        sleep(1)
        self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT,"HVSOCInfo",{"info":{"realSoc":100.0}})
        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetHVSOCInfo", {},
                                            {'out': {'realSoc': 100.0}})
        #UB等于1但信号不等于50
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr03,'HvBattSoc', 50.0)
        sleep(1)
        self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT,"HVSOCInfo",{"info":{"realSoc":50.0}})
        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetHVSOCInfo", {},
                                            {'out': {'realSoc': 50.0}})
            
