    @allure.title("通知和获取动力电池碰撞状态_E2E校验失败")
    @pytest.mark.full
    def test_caseid_110857(self):
        self.ipdu.set(self.ipdu.propulsioncan.SrsPropFr02, 'CrashStsSafeSts', 0)
        sleep(1)
        try:
            self.ipdu.set_no_crc(self.ipdu.propulsioncan.SrsPropFr02, 'CrashStsSafeSts')
            sleep(1)
            self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "HVCrash", {"state": True})
            self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetHVCrash", {},
                                                  {"out": True})
        except Exception as error:
            self.ipdu.restore_crc(self.ipdu.propulsioncan.SrsPropFr02, 'CrashStsSafeSts')
            assert False, error
        else:
            self.ipdu.restore_crc(self.ipdu.propulsioncan.SrsPropFr02, 'CrashStsSafeSts')
        sleep(1)
        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetHVCrash", {},
                                              {"out": False})
        self.ipdu.set(self.ipdu.propulsioncan.SrsPropFr02, 'CrashStsSafeSts', 1)
        sleep(1)
        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetHVCrash", {},
                                              {"out": True})
        
