    @allure.title("获取和通知充电信息_充电时间_开始到结束到重启记忆（信号代替接口）")
    @pytest.mark.full
    @pytest.mark.restart
    def test_caseid_1985331(self):
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr16, 'TotChrgEgy', 1000)
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr13, 'HvBattEgyAvlChrg1', 2000.0)
        self.ipdu.set(self.ipdu.backbonefr.VddmBackBoneFr16, 'ChrgnOrDisChrgnStsFb', 0)
        sleep(4)
        self.ipdu.set(self.ipdu.backbonefr.VddmBackBoneFr16, 'ChrgnOrDisChrgnStsFb', 30)
        sleep(1) #开始充电时间
        Starttime1 = self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetChargingInfo", {})["out"][
            'recentChargeStartTime']
        Starttime2 = self.partner.send_request_and_return_resp(TIMEMANANGEMENT_SERVICE_CLIENT, "GetVehicleTimeInfo", {})["out"][
            'UTCTime']
        C = time.strftime("%H%M%S", time.localtime(int(Starttime1 / 1000)))
        Realtime1 = int(C)
        Realtime = (Starttime2 + 80000000) // 1000
        Realtime2 = Realtime % 240000
        logger.info(f"{Realtime1*0.01}和{Realtime2*0.01}进行比较")
        # assert abs(Realtime1 - Realtime2) < 2
        abs(Realtime1*0.01 - Realtime2*0.01) < 0.5
        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetChargingInfo", {},
                                            {"out": {"recentChargeEndTime": 0}})#充电进行中
        self.ipdu.set(self.ipdu.backbonefr.VddmBackBoneFr16, 'ChrgnOrDisChrgnStsFb', 0)
        sleep(1)#结束充电时间
        Starttime3 = self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetChargingInfo", {})["out"][
            'recentChargeEndTime']
        Starttime4 = self.partner.send_request_and_return_resp(TIMEMANANGEMENT_SERVICE_CLIENT, "GetVehicleTimeInfo", {})["out"][
            'UTCTime']
        D = time.strftime("%H%M%S", time.localtime(int(Starttime3 / 1000)))
        Realtime3 = int(D)
        Realtime_1 = (Starttime4 + 80000000) // 1000
        Realtime4 = Realtime_1 % 240000
        logger.info(f"{Realtime3}和{Realtime4}进行比较")
        assert abs(Realtime3*0.01 - Realtime4*0.01) < 0.5
        self.restart_bgm_and_connect_service(HIGHVOLTAGE_SERVICE_CLIENT)
        sleep(2)
        Starttime5 = self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetChargingInfo", {})["out"][
            'recentChargeStartTime']
        Starttime6 = self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetChargingInfo", {})["out"][
            'recentChargeEndTime']
        assert Starttime5== Starttime1 and Starttime6== Starttime3
        
