    @allure.title("获取和通知充电信息_多次充电时充电时间逻辑处理")
    @pytest.mark.full
    def test_caseid_1985385(self):
        for chargingstate in [2,15,24,28,30]:
            logger.info(f"充电状态为{chargingstate}")
            self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr16, 'TotChrgEgy', 1000)
            self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr13, 'HvBattEgyAvlChrg1', 2000.0)
            self.ipdu.set(self.ipdu.backbonefr.VddmBackBoneFr16, 'ChrgnOrDisChrgnStsFb', 0)
            sleep(1)
            self.ipdu.set(self.ipdu.backbonefr.VddmBackBoneFr16, 'ChrgnOrDisChrgnStsFb', chargingstate)
            self.partner.empty_all(1)
            starttime1 = self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetChargingInfo", {},timeout=2)["out"][
                'recentChargeStartTime']
            Endtime1 = self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetChargingInfo", {},timeout=2)["out"][
                'recentChargeEndTime']
            assert starttime1 > 0 and Endtime1 == 0
            self.ipdu.set(self.ipdu.backbonefr.VddmBackBoneFr16, 'ChrgnOrDisChrgnStsFb', 0)
            sleep(1)
            Endtime2 = self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetChargingInfo", {},timeout=2)["out"][
                'recentChargeEndTime']
            assert Endtime2 > 0
            #再次充电
            self.ipdu.set(self.ipdu.backbonefr.VddmBackBoneFr16, 'ChrgnOrDisChrgnStsFb', 15)
            self.partner.empty_all(1)
            starttime2 = self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetChargingInfo", {},timeout=2)["out"][
                'recentChargeStartTime']
            Endtime3 = self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetChargingInfo", {},timeout=2)["out"][
                'recentChargeEndTime']
            assert starttime2 > starttime1 and Endtime3 == 0
            self.ipdu.set(self.ipdu.backbonefr.VddmBackBoneFr16, 'ChrgnOrDisChrgnStsFb', 0)
            sleep(1)
            Endtime4 = self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetChargingInfo", {},timeout=2)["out"][
                'recentChargeEndTime']
            assert Endtime4 > Endtime2
        
