    @allure.title("75度电池设置完目标SOC后，测试功能逻辑")
    @pytest.mark.full
    @pytest.mark.restart
    def test_caseid_1984803(self):
        self.sd_tester.write_single_ccp(566, 23)
        sleep(3)
        self.restart_bgm_and_connect_service(HIGHVOLTAGE_SERVICE_CLIENT)
        self.partner.send_method_request(HIGHVOLTAGE_SERVICE_CLIENT, "SetChargeSoc", {"soc": 50})
        sleep(3)
        self.restart_bgm_and_connect_service(HIGHVOLTAGE_SERVICE_CLIENT)
        sleep(0.5)
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr16, 'TotChrgEgy', 2000.0)
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr13, 'HvBattEgyAvlChrg1', 75000.0)
        self.ipdu.check(self.ipdu.backbonefr.IHUBackBoneFr12, 'LocalBookChrgnTarVal', 500, timeout=0.5)
        sleep(3)
        for Chargests1 in list(range(3,13)) +[0,1,14,29]+ list(range(18,24))+list(range(25,28)):
            for Chargests2 in [15,24]:
                logger.info(f"设置未充电时的充电状态为{Chargests1}")
                self.ipdu.set(self.ipdu.backbonefr.VddmBackBoneFr16, 'ChrgnOrDisChrgnStsFb', Chargests1)
                self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr13, 'HvBattEgyAvlChrg1', 75000.0)
                sleep(0.5)
                total1 = self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT,
                                                                    "GetChargingInfo", {},timeout=2)["out"]['totalChargeEnergy']#有重启
                self.partner.empty_all(1)
                self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr16, 'TotChrgEgy', total1 )
                sleep(1)
                self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetChargingInfo", {},
                                                    {"out": {"totalChargeEnergy": total1}})
                logger.info(f"设置充电状态从{Chargests1}到开始充电{Chargests2}")
                self.ipdu.set(self.ipdu.backbonefr.VddmBackBoneFr16, 'ChrgnOrDisChrgnStsFb', Chargests2)
                sleep(1)
                self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr13, 'HvBattEgyAvlChrg1', 55000.0)
                sleep(1)
                self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr13, 'HvBattEgyAvlChrg1', 0.0)
                sleep(1)
                logger.info(f"设置从{Chargests2}充电状态为结束{Chargests1}")
                self.ipdu.set(self.ipdu.backbonefr.VddmBackBoneFr16, 'ChrgnOrDisChrgnStsFb', Chargests1)
                sleep(1)
                self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "ChargingInfo", {"info":
                                        {"totalChargeEnergy": 75000 + total1,"chargeEnergyThisTime":75000}})
                self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetChargingInfo", {},
                                        {"out": {"totalChargeEnergy": 75000 + total1, "chargeEnergyThisTime":75000}},timeout=2)
                    
