        sleep(2) #清除初始值
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr15, 'DCChrgnHndlSts', 1)
        sleep(1) #清除本次增加续航
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr04, 'HvBattEgyCdn', 99.0)
        self.ipdu.set(self.ipdu.propulsioncan.EcmPropFr04, 'DispHvBattLvlOfChrg', 100.0)
        self.ipdu.set(self.ipdu.chassiscan1.EcmChas1Fr13, 'BookChrgnTarValFb', 100.0)
        self.partner.send_method_request(HIGHVOLTAGE_SERVICE_CLIENT, "SetRange",
                                            {"infos": {"type": 0, "CLTCRange": 999, "estimatedRange": 999}})
        self.partner.send_method_request(HIGHVOLTAGE_SERVICE_CLIENT, "SetAveragePowerConsume", {"power": 50})
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr15, 'DCChrgnHndlSts', 0)
        sleep(1) #清除本次增加续航
        self.restart_bgm_and_connect_service(HIGHVOLTAGE_SERVICE_CLIENT)
        # type=0 时targetRange跟随targetCLTCRange
        # range无效时 所有参数的表现
        self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "NotifyRange", {"infos": 
                                                            {"type":0,"source": 1, "targetRange":720,"targetCLTCRange": 720,
                                                             "targetEstimatedRange": 193,"CLTCRange":720,"estimatedRange":193}},timeout=2)
        self.ipdu.set(self.ipdu.propulsioncan.EcmPropFr04, 'DispHvBattLvlOfChrg', 0.0)
        sleep(2) #电量为0
        self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "NotifyRange", {"infos": 
                                                            {"type":0,"source": 1, "targetRange":720,"targetCLTCRange": 720,
                                                             "targetEstimatedRange": 193,"CLTCRange":0,"estimatedRange":0}})
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr15, 'DCChrgnHndlSts', 1)
        sleep(1) #准备重新开始充电,本次充电清零
        self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "NotifyRange", {"infos": 
                                                            {"type":0,"source": 1, "targetRange":720,"targetCLTCRange": 720,
                                                             "targetEstimatedRange": 193,"CLTCRange":0,"estimatedRange":0,
                                                             "CLTCRangeIncrease": 0,"estimatedRangeIncrease":0}})
        self.ipdu.set(self.ipdu.backbonefr.VddmBackBoneFr16, 'ChrgnOrDisChrgnStsFb', 15)
        sleep(1)
        self.ipdu.set(self.ipdu.propulsioncan.EcmPropFr04, 'DispHvBattLvlOfChrg', 50.0)
        self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "NotifyRange", {"infos": 
                                                            {"type":0,"source": 1, "targetRange":720,"targetCLTCRange": 720,
                                                             "targetEstimatedRange": 193,"CLTCRange":360,"estimatedRange":96,
                                                             "CLTCRangeIncrease": 360,"estimatedRangeIncrease":96}})
        self.ipdu.set(self.ipdu.backbonefr.VddmBackBoneFr16, 'ChrgnOrDisChrgnStsFb', 0)
        self.partner.empty_all(1) #停止充电后电量消耗到30%
        self.ipdu.set(self.ipdu.propulsioncan.EcmPropFr04, 'DispHvBattLvlOfChrg', 49.0) #保证计算周期
        self.partner.empty_all(1)
        self.ipdu.set(self.ipdu.propulsioncan.EcmPropFr04, 'DispHvBattLvlOfChrg', 30.0)
        self.partner.empty_all(1)
        self.ipdu.set(self.ipdu.backbonefr.VddmBackBoneFr16, 'ChrgnOrDisChrgnStsFb', 15)
        self.partner.empty_all(1)#又开始充电
        self.ipdu.set(self.ipdu.propulsioncan.EcmPropFr04, 'DispHvBattLvlOfChrg', 100.0)
        self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "NotifyRange", {"infos": 
                                                            {"type":0,"source": 1, "targetRange":720,"targetCLTCRange": 720,
                                                             "targetEstimatedRange": 193,"CLTCRange":720,"estimatedRange":193,
                                                             "CLTCRangeIncrease": 720,"estimatedRangeIncrease":193}})
        self.ipdu.set(self.ipdu.backbonefr.VddmBackBoneFr16, 'ChrgnOrDisChrgnStsFb', 0)
        self.partner.empty_all(1)#停止充电拔枪
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr15, 'DCChrgnHndlSts', 0)
        
