    @allure.title("通知和获取预约充电时间_遍历蓝牙和远程在重启后ChrgPilBookChrgn=1时再次上报event")
    @pytest.mark.restart
    @pytest.mark.full
    def test_caseid_1984593(self):
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr15, 'DCChrgnHndlSts', 1) #防止预约充电为0默认值
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr33, 'RemoteBookStrtTiChrgnTmrChrgnTmrhour', 24)
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr33, 'RemoteBookStrtTiChrgnTmrChrgnTmrmin', 60)
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr33, 'RemoteBookStopTiChrgnTmrChrgnTmrhour', 24)
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr33, 'RemoteBookStopTiChrgnTmrChrgnTmrmin', 60)
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr32, 'ChrgPilBookChrgn', 2)
        self.partner.empty_all()
        for state in [0,1,3]:
            logger.info(f"发送信号蓝牙={state}")
            self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr32, 'BthBookStrtTiChrgnTmrChrgnTmrhour', 10)
            self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr32, 'BthBookStrtTiChrgnTmrChrgnTmrmin', 10)
            self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr32, 'BthBookStopTiChrgnTmrChrgnTmrhour', 10)
            self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr32, 'BthBookStopTiChrgnTmrChrgnTmrmin', 10)
            self.partner.empty_all(0.5)
            self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr32, 'ChrgPilBookChrgn', state)
            self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr32, 'BthBookStrtTiChrgnTmrChrgnTmrhour', 0)
            self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr32, 'BthBookStrtTiChrgnTmrChrgnTmrmin', 59)
            self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr32, 'BthBookStopTiChrgnTmrChrgnTmrhour', 0)
            self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr32, 'BthBookStopTiChrgnTmrChrgnTmrmin', 59)
            self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT,'BookChargingTime',{'info':{'type': 1, 'startTime': {'kHour': 0,
                                                                'kMinute': 59},'endTime': {'kHour': 0, 'kMinute': 59}}})
            self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetBookChargingTime", {"type": 0},
                                              {'out': {'type': 1, 'startTime': {'kHour': 0, 'kMinute': 59},
                                                       'endTime': {'kHour': 0,'kMinute': 59}}})
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr32, 'ChrgPilBookChrgn', 1)
        sleep(1)
        self.restart_bgm_and_connect_service(HIGHVOLTAGE_SERVICE_CLIENT)
        self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT,'BookChargingTime',{'info':{'type': 1, 'startTime': {'kHour': 0,
                                                                'kMinute': 59},'endTime': {'kHour': 0, 'kMinute': 59}}})
        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetBookChargingTime", {"type": 0},
                                              {'out': {'type': 1, 'startTime': {'kHour': 0, 'kMinute': 59},
                                                       'endTime': {'kHour': 0,'kMinute': 59}}})
        for state in [0,1,3]:
            logger.info(f"发送信号远控={state}")
            self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr33, 'RemoteBookStrtTiChrgnTmrChrgnTmrhour', 10)
            self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr33, 'RemoteBookStrtTiChrgnTmrChrgnTmrmin', 10)
            self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr33, 'RemoteBookStopTiChrgnTmrChrgnTmrhour', 10)
            self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr33, 'RemoteBookStopTiChrgnTmrChrgnTmrmin', 10)
            self.partner.empty_all(0.5)
            self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr32, 'ChrgPilBookChrgn', state)
            self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr33, 'RemoteBookStrtTiChrgnTmrChrgnTmrhour', 12)
            self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr33, 'RemoteBookStrtTiChrgnTmrChrgnTmrmin', 24)
            self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr33, 'RemoteBookStopTiChrgnTmrChrgnTmrhour', 12)
            self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr33, 'RemoteBookStopTiChrgnTmrChrgnTmrmin', 24)
            self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT,'BookChargingTime',{'info':{'type': 2, 'startTime': {'kHour': 12,
                                                                'kMinute': 24},'endTime': {'kHour': 12, 'kMinute': 24}}})
            self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetBookChargingTime", {"type": 0},
                                              {'out': {'type': 2, 'startTime': {'kHour': 12, 'kMinute': 24},
                                                       'endTime': {'kHour': 12,'kMinute': 24}}})
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr32, 'ChrgPilBookChrgn', 1)
        self.restart_bgm_and_connect_service(HIGHVOLTAGE_SERVICE_CLIENT)
        self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT,'BookChargingTime',{'info':{'type': 2, 'startTime': {'kHour': 12,
                                                                'kMinute': 24},'endTime': {'kHour': 12, 'kMinute': 24}}})
        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetBookChargingTime", {"type": 0},
                                              {'out': {'type': 2, 'startTime': {'kHour': 12, 'kMinute': 24},
                                                       'endTime': {'kHour': 12,'kMinute': 24}}})
        
