    @allure.title("获取和通知电机信息_400V和800V遍历")
    @pytest.mark.full
    @pytest.mark.restart
    def test_caseid_1984682(self):
        self.sd_tester.write_multi_ccp({3: 129, 4: 6,950:1,962:0})
        self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr06, 'IsgTqActIsgTqAct', 0.0)
        self.ipdu.set(self.ipdu.propulsioncan.IemEduPropFr01, 'WhlMotSysTqEstIsgTqAct',0.0)
        self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr06, 'IsgSpdActSgn', 0.0)
        self.ipdu.set(self.ipdu.propulsioncan.IemEduPropFr02, 'WhlMotSysSpdAct',0.0)
        self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr05, 'IsgUDc', 0.0)
        self.ipdu.set(self.ipdu.propulsioncan.IemEduPropFr02, 'WhlMotSysUdc',0.0)
        sleep(3)
        self.restart_bgm_and_connect_service(HIGHVOLTAGE_SERVICE_CLIENT)
        sleep(1)
        #前后电机转速
        for speed in [-16384.0,0.0,16383.0]:
            logger.info(f"--转速发送{speed}")
            self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr06, 'IsgSpdActSgn', speed)
            self.ipdu.set(self.ipdu.propulsioncan.IemEduPropFr02, 'WhlMotSysSpdAct',speed)
            sleep(0.5)
            self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "MotorInfo",
                                    {"motorsInfo": [{"motorId": 0,"rotationalSpeed": speed},{"motorId": 1,"rotationalSpeed": speed}]})
            self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetMotorInfo", {"motors": [0,1]},
                                    {"out": [{"motorId": 0,"rotationalSpeed": speed},{"motorId": 1,"rotationalSpeed": speed}]})
            self.partner.empty_all()
        #前后电机扭矩
        for toque in [-8188.0,0.0,8192.0]:
            logger.info(f"--扭矩发送{toque}")
            self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr06, 'IsgTqActIsgTqAct', toque)
            self.ipdu.set(self.ipdu.propulsioncan.IemEduPropFr01, 'WhlMotSysTqEstIsgTqAct',toque)
            sleep(0.5)
            self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "MotorInfo",
                                    {"motorsInfo":[{"motorId": 0,"motorTorque":{"torque": toque}},{"motorId": 1,"motorTorque":{"torque": toque}}]})
            self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetMotorInfo", {"motors": [0,1]},
                                    {"out": [{"motorId": 0,"motorTorque":{"torque": toque}},{"motorId": 1,"motorTorque":{"torque": toque}}]})
            self.partner.empty_all()
        #前后电机电压
        for voltage in [100.0,0.0,511.0]:
            logger.info(f"--电压发送{voltage}")
            self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr05, 'IsgUDc', voltage)
            self.ipdu.set(self.ipdu.propulsioncan.IemEduPropFr02, 'WhlMotSysUdc',voltage)
            sleep(0.5)
            self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "MotorInfo",
                                    {"motorsInfo": [{"motorId": 0,"inputVoltage": voltage},{"motorId": 1,"inputVoltage": voltage}]})
            self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetMotorInfo", {"motors": [0,1]},
                                    {"out": [{"motorId": 0,"inputVoltage": voltage},{"motorId": 1,"inputVoltage": voltage}]})
            self.partner.empty_all()
        #前后电机电流
        for current in [-818.0,0.0,819.0]:
            logger.info(f"--电流发送{current}")
            self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr03, 'IsgIDc', current)
            self.ipdu.set(self.ipdu.propulsioncan.IemPropFr08, 'WhlMotSysIdc',current)
            sleep(0.5)
            self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "MotorInfo",
                                    {"motorsInfo": 
                                     [{"motorId": 0,"busbarCurrent": current},{"motorId": 1,"busbarCurrent": current}]})
            self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetMotorInfo", {"motors": [0,1]},
                                    {"out": [{"motorId": 0,"busbarCurrent": current},{"motorId": 1,"busbarCurrent": current}]})
            self.partner.empty_all()
        self.sd_tester.write_single_ccp(962,2) #800V
        sleep(3)
        self.restart_bgm_and_connect_service(HIGHVOLTAGE_SERVICE_CLIENT)
        sleep(1)
