    @allure.title("通知和获取充电桩信息_chargePowerInput遍历_400V")
    @pytest.mark.full
    def test_caseid_1984684(self):
        def info(voltage,current):
            return abs(voltage*current)
        self.sd_tester.write_single_ccp(962,0)
        self.ipdu.set(self.ipdu.backbonefr.VddmBackBoneFr16, 'ChrgnOrDisChrgnStsFb', 0)
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr15, 'DCChrgnHndlSts', 0)
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr01, 'HvBattUDc', 400.0)
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr01, 'HvBattUDc800', 10.0)
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr22, 'ChrgEquipIDc', 0.0)
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr01, 'HvBattUDc', 0.0)
        self.partner.empty_all(3)
        self.restart_bgm_and_connect_service(HIGHVOLTAGE_SERVICE_CLIENT,pause_all_bus=True, resume_all_bus=False)
        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "getEquipmentInfo", {},
                                                {"out": {"chargePowerInput":  -1}})
        self.ipdu.resume_all_bus_send()
        sleep(2)
        #仅电流变化时
        for voltage1 in [511.0]:
            for current1 in [-1638.0,0.0,1637.0,100.0]:
                self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr01, 'HvBattUDc', voltage1)
                sleep(1)
                logger.info(f"发送电流={current1}")
                self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr22, 'ChrgEquipIDc', current1)
                sleep(1)
                self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "NotifyChargingEquipmentInformation",
                                        {"info": {"chargePowerInput": info(voltage1,current1)}})
                self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "getEquipmentInfo", {},
                                                    {"out": {"chargePowerInput": info(voltage1,current1)}})
        #仅电压有效变化时
        for voltage3 in [200.0,300.0,511.0]:
            logger.info(f"发送电压={voltage3}")
            self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr01, 'HvBattUDc', voltage3)
            self.partner.empty_all(1)
            self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "getEquipmentInfo", {},
                                                {"out": {"chargePowerInput":  51100}})
        #仅电压无效变化时
        for voltage2 in [0.0,100.0,199.0]:
            logger.info(f"发送电压={voltage2}")
            self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr01, 'HvBattUDc', voltage2)
            self.partner.empty_all(1)
            self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "getEquipmentInfo", {},
                                                {"out": {"chargePowerInput":  51100}})
        #电压无效电流有效时
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr22, 'ChrgEquipIDc', 10.0)
        sleep(1)
        self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "NotifyChargingEquipmentInformation",
                                    {"info": {"chargePowerInput":  5110}})
        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "getEquipmentInfo", {},
                                                {"out": {"chargePowerInput":  5110}})
        #电压电流恢复
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr01, 'HvBattUDc', 500.0)
        sleep(1)
        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "getEquipmentInfo", {},
                                                {"out": {"chargePowerInput":  5110}})
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr22, 'ChrgEquipIDc', 20.0)
        sleep(1)
        self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "NotifyChargingEquipmentInformation",
                                    {"info": {"chargePowerInput": 10000.0}})
        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "getEquipmentInfo", {},
                                                {"out": {"chargePowerInput":  10000}})
        #最大值
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr01, 'HvBattUDc', 511.0)
        sleep(0.5)
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr22, 'ChrgEquipIDc', 1638.7)
        sleep(0.5)
        # self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "NotifyChargingEquipmentInformation",
        #                             {"info": {"chargePowerInput":837375.6875}})
        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "getEquipmentInfo", {},
                                                {"out": {"chargePowerInput":837375.6875}}) 
        
