    @allure.title("通知和能量消耗信息_batteryPureEnergy_最新计算逻辑")
    @pytest.mark.smoke
    @pytest.mark.restart
    def test_caseid_1985720(self):
        self.ipdu.set(self.ipdu.propulsioncan.EcmPropFr24, 'EngSt1WdStsEngSt1WdSts', 0)
        self.ipdu.set(self.ipdu.chassiscan2.EcmChas2Fr16, 'DispBattEgyIn', 0)
        self.ipdu.set(self.ipdu.chassiscan2.EcmChas2Fr16, 'DispBattEgyOut', 0)
        self.ipdu.set(self.ipdu.propulsioncan.EcmPropFr24, 'EngSt1WdStsEngSt1WdSts', 6)
        self.restart_bgm_and_connect_service(HIGHVOLTAGE_SERVICE_CLIENT)
        sleep(1)
        self.ipdu.set(self.ipdu.chassiscan2.EcmChas2Fr16, 'DispBattEgyIn', 40)
        self.ipdu.set(self.ipdu.chassiscan2.EcmChas2Fr16, 'DispBattEgyOut', 40)
        #拿出PowerConsumptionInfo做比较
        self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "PowerConsumptionInfo", {'powerConsumptionInfo':
                                                                                           {'outputEnergy': 20.0,
                                                                                            'recoveryEnergy': 20.0}})
        sleep(1)
        base1 = self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetEnergyConsumptionInfo", {})["out"][
            'batteryPureEnergy']
        self.partner.empty_all(1)
        logger.info(f"此时的basebatteryPureEnergy为{base1}")
        sleep(1)#输出发80时
        self.ipdu.set(self.ipdu.chassiscan2.EcmChas2Fr16, 'DispBattEgyIn', 40)
        self.ipdu.set(self.ipdu.chassiscan2.EcmChas2Fr16, 'DispBattEgyOut', 80)
        self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "EnergyConsumptionInfo", 
                                  {'info':{'batteryPureEnergy': base1 +0.02}}) #增量为（80）x0.5x0.001
        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetEnergyConsumptionInfo",{},
                                              {"out":{'batteryPureEnergy': base1 +0.02}},timeout=2.0) 
        #输出发100时
        self.ipdu.set(self.ipdu.chassiscan2.EcmChas2Fr16, 'DispBattEgyIn', 50)
        self.ipdu.set(self.ipdu.chassiscan2.EcmChas2Fr16, 'DispBattEgyOut', 100)
        self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "EnergyConsumptionInfo", 
                                  {'info':{'batteryPureEnergy': base1 +0.025}}) #增量为（100-50）x0.5x0.001
        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetEnergyConsumptionInfo",{},
                                              {"out":{'batteryPureEnergy': base1 +0.025}},timeout=2.0) 
        self.partner.empty_all(7)
        # self.restart_bgm_and_connect_service(HIGHVOLTAGE_SERVICE_CLIENT)
        self.sd_tester.send_data([0x11,0x81])
        self.partner.wait_for_service_reconnect(HIGHVOLTAGE_SERVICE_CLIENT)
        self.ipdu.set(self.ipdu.chassiscan2.EcmChas2Fr16, 'DispBattEgyIn', 0)
        self.ipdu.set(self.ipdu.chassiscan2.EcmChas2Fr16, 'DispBattEgyOut', 0)
        sleep(1)
        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetEnergyConsumptionInfo",{},
                                              {"out":{'batteryPureEnergy': base1 +0.025}},timeout=2.0) 
        self.ipdu.set(self.ipdu.chassiscan2.EcmChas2Fr16, 'DispBattEgyIn', 40)
        self.ipdu.set(self.ipdu.chassiscan2.EcmChas2Fr16, 'DispBattEgyOut', 80)
        sleep(1)
        self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "EnergyConsumptionInfo", 
                                  {'info':{'batteryPureEnergy': base1 +0.025+ 0.02}}) #增量为（100-50）x0.5x0.001
        
