        sleep(1)#再次上driving，#此时最新base2=base1+0.04
        self.ipdu.set(self.ipdu.chassiscan2.EcmChas2Fr16, 'DispBattEgyIn', 100)
        self.ipdu.set(self.ipdu.chassiscan2.EcmChas2Fr16, 'DispBattEgyOut', 120) #增量为50x0.001 基础out=120 input=70
        self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "EnergyConsumptionInfo", 
                                  {'info':{'batteryPureEnergy': base1 +0.03}}) 
        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetEnergyConsumptionInfo",{},
                                              {"out":{'batteryPureEnergy': base1 +0.03}})
        self.ipdu.set(self.ipdu.propulsioncan.EcmPropFr24, 'EngSt1WdStsEngSt1WdSts', 0)
