    @allure.title("通知和能量消耗信息_powerTrainEnergy 和regenerateEnergy_双电机800V计算逻辑")
    @pytest.mark.full
    @pytest.mark.restart
    def test_caseid_1985603(self):
        self.sd_tester.write_multi_ccp({3: 129, 4: 6,950:1,962:2}) #4:6代表双电机，962：2代表800V
        self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr05, 'IsgUDc', 0)
        self.ipdu.set(self.ipdu.propulsioncan.IemEduPropFr02, 'WhlMotSysUdc',0)
        self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr03, 'IsgIDc', 0)
        self.ipdu.set(self.ipdu.propulsioncan.IemPropFr08, 'WhlMotSysIdc',0)
        self.ipdu.set(self.ipdu.propulsioncan.EcmPropFr24, 'EngSt1WdStsEngSt1WdSts', 0)
        self.ipdu.set(self.ipdu.chassiscan2.EcmChas2Fr16, 'DispBattEgyIn', 0)
        self.ipdu.set(self.ipdu.chassiscan2.EcmChas2Fr16, 'DispBattEgyOut', 0)
        self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr05, 'IsgUDc800', 0.0)
        self.ipdu.set(self.ipdu.propulsioncan.IemPropFr08,'WhlMotSysUDc800',0.0)
        sleep(3)
        self.restart_bgm_and_connect_service(HIGHVOLTAGE_SERVICE_CLIENT)
        sleep(1)
        #前后电机电流都是正
        self.sd_tester.change_usage_mode(13)
        self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr05, 'IsgUDc', 500)
        self.ipdu.set(self.ipdu.propulsioncan.IemEduPropFr02, 'WhlMotSysUdc',500)
        self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr05, 'IsgUDc800', 1000.0)
        self.ipdu.set(self.ipdu.propulsioncan.IemPropFr08,'WhlMotSysUDc800',1000.0)
        sleep(1)
        self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr03, 'IsgIDc', 10.0)
        self.ipdu.set(self.ipdu.propulsioncan.IemPropFr08, 'WhlMotSysIdc',10.0)
        sleep(1)
        #拿出PowerConsumptionInfo做比较
        powerTrainEnergy1 = self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT,
                                                                      "GetEnergyConsumptionInfo", {})["out"]['powerTrainEnergy']
        regenerateEnergy1 = self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT,
                                                                      "GetEnergyConsumptionInfo", {})["out"]['regenerateEnergy']
        logger.info(f"初始机械功率为{powerTrainEnergy1}和回收功率为{regenerateEnergy1}")
        self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr03, 'IsgIDc', 800.0)
        self.ipdu.set(self.ipdu.propulsioncan.IemPropFr08, 'WhlMotSysIdc',800.0)
        sleep(50)
        self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr03, 'IsgIDc', 0.0)
        self.ipdu.set(self.ipdu.propulsioncan.IemPropFr08, 'WhlMotSysIdc',0.0)
        sleep(1)
        powerTrainEnergy2 = self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT,
                                                                      "GetEnergyConsumptionInfo", {})["out"]['powerTrainEnergy']
        BGMcalue1=powerTrainEnergy2-powerTrainEnergy1
        logger.info(f"BGM计算机械功率为{powerTrainEnergy2}及50S计算差值为{BGMcalue1}")
        assert abs(BGMcalue1-80000/3600)< 0.5 #框架问题+浮点数计算有偏差，加大校验偏差
        self.partner.empty_all()#d都为负数
        self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr03, 'IsgIDc', -200.0)
        self.ipdu.set(self.ipdu.propulsioncan.IemPropFr08, 'WhlMotSysIdc',-300.0)
        sleep(50)
        self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr03, 'IsgIDc', 0.0)
        self.ipdu.set(self.ipdu.propulsioncan.IemPropFr08, 'WhlMotSysIdc',0.0)
        sleep(1)
        regenerateEnergy2 = self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT,
                                                                      "GetEnergyConsumptionInfo", {},timeout=2.0)["out"]['regenerateEnergy']
        BGMcalue2=regenerateEnergy2-regenerateEnergy1
        logger.info(f"BGM回收功率为{regenerateEnergy2}及50S计算差值为{BGMcalue2}")
        assert abs(BGMcalue2-25000/3600)< 0.1
        sleep(2)
        self.sd_tester.reset_ecu()#正常下电
        self.partner.wait_for_service_reconnect(HIGHVOLTAGE_SERVICE_CLIENT)
        sleep(1)
        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetEnergyConsumptionInfo",{},
                                              {"out":{'powerTrainEnergy': powerTrainEnergy2,
                                                      "regenerateEnergy":regenerateEnergy2}},timeout=2.0) 
        
    @allure.title("通知和能量消耗信息_thermalEnergy和cabinEnergy_计算逻辑")
    @pytest.mark.sanity
    def test_caseid_1985607(self):
        self.sd_tester.write_multi_ccp({3: 129, 4: 6,950:1,962:0})
        self.ipdu.set(self.ipdu.chassiscan1.EcmChas1Fr19, 'HvBattThermPwrCns', 0.0)
        self.ipdu.set(self.ipdu.chassiscan1.EcmChas1Fr41, 'HvCabinThermPwrCns', 0.0)
        sleep(1)
        #拿出PowerConsumptionInfo做比较
        thermalEnergy1 = self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT,
                                                                      "GetEnergyConsumptionInfo", {})["out"]['thermalEnergy']
        cabinEnergy1 = self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT,
                                                                      "GetEnergyConsumptionInfo", {})["out"]['cabinEnergy']
        self.ipdu.set(self.ipdu.chassiscan1.EcmChas1Fr19, 'HvBattThermPwrCns', 18000.0)
        self.ipdu.set(self.ipdu.chassiscan1.EcmChas1Fr41, 'HvCabinThermPwrCns', 18000.0)
        sleep(20)
        self.ipdu.set(self.ipdu.chassiscan1.EcmChas1Fr19, 'HvBattThermPwrCns', 0.0)
        self.ipdu.set(self.ipdu.chassiscan1.EcmChas1Fr41, 'HvCabinThermPwrCns', 0.0)
        sleep(3)#一直在计算，导致重启后拿到的值不是最新值
        thermalEnergy2 = self.partner.return_latest_event(HIGHVOLTAGE_SERVICE_CLIENT,
                                                                      "EnergyConsumptionInfo")["info"]['thermalEnergy']
        cabinEnergy2 = self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT,
                                                                      "GetEnergyConsumptionInfo", {})["out"]['cabinEnergy']
        BGMcalue1=thermalEnergy2-thermalEnergy1
        BGMcalue2=cabinEnergy2-cabinEnergy1
        logger.info(f"座舱20S增加量为{BGMcalue2}和热量20S增加量为{BGMcalue1}")
        assert abs(BGMcalue1-0.1)<0.1
        assert abs(BGMcalue2-0.1)<0.1
        sleep(3)#记忆项，异常下电走5S逻辑，补充case走诊断重启
        self.restart_bgm_and_connect_service(HIGHVOLTAGE_SERVICE_CLIENT)
        sleep(1)
        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetEnergyConsumptionInfo",{},
                                    {"out":{'thermalEnergy': thermalEnergy2,"cabinEnergy":cabinEnergy2}})
        
