        self.ipdu.set(self.ipdu.propulsioncan.EcmPropFr24, 'EngSt1WdStsEngSt1WdSts', 6)
        self.ipdu.set(self.ipdu.chassiscan2.EcmChas2Fr16, 'DispBattEgyIn', 0)
        self.ipdu.set(self.ipdu.chassiscan2.EcmChas2Fr16, 'DispBattEgyOut', 0)
        sleep(3)
        self.restart_bgm_and_connect_service(HIGHVOLTAGE_SERVICE_CLIENT)
        sleep(1)
        #拿出PowerConsumptionInfo做比较
        self.ipdu.set(self.ipdu.chassiscan2.EcmChas2Fr16, 'DispBattEgyIn', 40.0)
        self.ipdu.set(self.ipdu.chassiscan2.EcmChas2Fr16, 'DispBattEgyOut', 40.0)
        sleep(1)
        regenerateEnergy1 = self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT,
                                                                      "GetEnergyConsumptionInfo", {})["out"]['regenerateEnergy']
        base1 = self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT,
                                                                      "GetEnergyConsumptionInfo", {})["out"]['batteryPureEnergy']
        logger.info(f"初始和回收功率为{regenerateEnergy1}和电池净输出能量为{base1}")
        sleep(1)
        for sigin1 in [10.0,20.0,30.0]:
            self.ipdu.set(self.ipdu.chassiscan2.EcmChas2Fr16, 'DispBattEgyIn', sigin1)
            sleep(1)
        for sigin2 in [10.0,20.0,30.0,40.0,50.0,60.0,70.0,80.0,90.0,100.0,110.0,120.0,130.0]:
            self.ipdu.set(self.ipdu.chassiscan2.EcmChas2Fr16, 'DispBattEgyOut', sigin2)
            sleep(1)  
        batteryPureEnergy1 = self.partner.return_latest_event(HIGHVOLTAGE_SERVICE_CLIENT,
                                                                    "EnergyConsumptionInfo")["info"]['batteryPureEnergy']
        self.sd_tester.change_usage_mode(13)
        self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr05, 'IsgUDc', 500.0)
        self.ipdu.set(self.ipdu.propulsioncan.IemEduPropFr02, 'WhlMotSysUdc',500.0)
        sleep(1)
        self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr03, 'IsgIDc', -800.0)
        self.ipdu.set(self.ipdu.propulsioncan.IemPropFr08, 'WhlMotSysIdc',-800.0)
        sleep(50)
        self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr03, 'IsgIDc', 0.0)
        self.ipdu.set(self.ipdu.propulsioncan.IemPropFr08, 'WhlMotSysIdc',0.0)
        sleep(2)
        totalEnergy1 = self.partner.return_latest_event(HIGHVOLTAGE_SERVICE_CLIENT,
                                                                    "EnergyConsumptionInfo")["info"]['totalEnergy']
        regenerateEnergy2 = self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT,
                                                                      "GetEnergyConsumptionInfo", {})["out"]['regenerateEnergy']
        base2 = self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT,
                                                                      "GetEnergyConsumptionInfo", {})["out"]['batteryPureEnergy']
        logger.info(f"最新发电量为{regenerateEnergy2}并且最新总能量为{totalEnergy1}")
        totalEnergy2= regenerateEnergy2+batteryPureEnergy1
        assert abs(totalEnergy1-totalEnergy2)<0.0101
        self.sd_tester.change_usage_mode(1)
        self.restart_bgm_and_connect_service(HIGHVOLTAGE_SERVICE_CLIENT)
        self.ipdu.set(self.ipdu.chassiscan2.EcmChas2Fr16, 'DispBattEgyIn', 0.0)
        self.ipdu.set(self.ipdu.chassiscan2.EcmChas2Fr16, 'DispBattEgyOut', 0.0)
        sleep(1)
        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetEnergyConsumptionInfo",{},
                                              {"out":{'totalEnergy': totalEnergy1,"batteryPureEnergy":base2}},timeout=2.0)
        logger.info(f"重启后的总量为为{totalEnergy1}并且重启前的净输出能量为{base1}最新净输出能量为{base2}")
        assert totalEnergy1 > base2 and base2 > base1
        
