        self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr03, 'IsgIDc', 100.0)
        self.ipdu.set(self.ipdu.propulsioncan.IemPropFr08, 'WhlMotSysIdc',100.0)
        sleep(0.5)
        #拿出PowerConsumptionInfo做比较
        powerTrainEnergy1 = self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT,
                                                                      "GetEnergyConsumptionInfo", {},timeout=2)["out"]['powerTrainEnergy']
        regenerateEnergy1 = self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT,
                                                                      "GetEnergyConsumptionInfo", {},timeout=2)["out"]['regenerateEnergy']
        logger.info(f"初始机械功率为{powerTrainEnergy1}和回收功率为{regenerateEnergy1}")
        self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr03, 'IsgIDc', 800.0)
        self.ipdu.set(self.ipdu.propulsioncan.IemPropFr08, 'WhlMotSysIdc',800.0)
        sleep(50)
        self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr03, 'IsgIDc', 0.0)
        self.ipdu.set(self.ipdu.propulsioncan.IemPropFr08, 'WhlMotSysIdc',0.0)
        sleep(1)
        powerTrainEnergy2 = self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT,
                                                                      "GetEnergyConsumptionInfo", {},timeout=2)["out"]['powerTrainEnergy']
        BGMcalue1=powerTrainEnergy2-powerTrainEnergy1
        logger.info(f"BGM计算机械功率为{powerTrainEnergy2}及50S计算差值为{BGMcalue1}")
        assert abs(BGMcalue1-40000/3600)< 0.1
        self.partner.empty_all()#d都为负数
        self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr03, 'IsgIDc', -200.0)
        self.ipdu.set(self.ipdu.propulsioncan.IemPropFr08, 'WhlMotSysIdc',-300.0)
        sleep(50)
        self.ipdu.set(self.ipdu.propulsioncan.IgmMgmPropFr03, 'IsgIDc', 0.0)
        self.ipdu.set(self.ipdu.propulsioncan.IemPropFr08, 'WhlMotSysIdc',0.0)
        sleep(1)
        regenerateEnergy2 = self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT,
                                                                      "GetEnergyConsumptionInfo", {},timeout=2)["out"]['regenerateEnergy']
        BGMcalue2=regenerateEnergy2-regenerateEnergy1
        logger.info(f"BGM回收功率为{regenerateEnergy2}及50S计算差值为{BGMcalue2}")
        assert abs(BGMcalue2-12500/3600)< 0.5 #因为是float，在想输入电流=0时，但是实际不为0，导致结果偏差较大，偶发失败
        sleep(1)
        self.restart_bgm_and_connect_service(HIGHVOLTAGE_SERVICE_CLIENT)
        sleep(1)
        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetEnergyConsumptionInfo",{},
                                              {"out":{'powerTrainEnergy': powerTrainEnergy2,
                                                      "regenerateEnergy":regenerateEnergy2}},timeout=3.0)
        
