    @allure.title("获取和通知充电信息_开始充电时间_时间未同步到同步")
    @pytest.mark.full
    @pytest.mark.restart
    def test_caseid_1985437(self):
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr16, 'TotChrgEgy', 1000)
        self.ipdu.set(self.ipdu.backbonefr.VddmBackBoneFr16, 'ChrgnOrDisChrgnStsFb', 0)
        self.partner.empty_all(1)
        self.nucapp.tcam_power_off()
        sleep(25)
        self.restart_bgm_and_connect_service(VEHICLETIME_SERVICE_CLIENT)
        sleep(2)
        self.partner.send_request_and_ck_resp(VEHICLETIME_SERVICE_CLIENT, "GetVehicleTimeInfo",{},{"out":{"SynchronizationStatus": 0}})
        self.ipdu.set(self.ipdu.backbonefr.VddmBackBoneFr16, 'ChrgnOrDisChrgnStsFb', 15)
        self.partner.empty_all(5)#开始充电时间
        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetChargingInfo",{},{"out":{"recentChargeStartTime": 0}})
        sleep(1)
        self.nucapp.tcam_power_on()
        self.partner.ck_s2s_event(VEHICLETIME_SERVICE_CLIENT, "VehicleTimeInfo",{"info":{"SynchronizationStatus": 3}},timeout=240)
        sleep(0.5)
        Starttime1 = self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetChargingInfo", {},timeout=2)["out"][
            'recentChargeStartTime']
        Starttime2 = self.partner.send_request_and_return_resp(TIMEMANANGEMENT_SERVICE_CLIENT, "GetVehicleTimeInfo", {},timeout=2)["out"][
            'UTCTime']
        C = time.strftime("%H%M%S", time.localtime(int(Starttime1 / 1000)))
        Realtime1 = int(C)
        Realtime = (Starttime2 + 80000000) // 1000
        Realtime2 = Realtime % 240000
        logger.info(f"{Realtime1}和{Realtime2}进行比较")
        assert abs(Realtime1*0.01 - Realtime2*0.01) < 0.5
        self.ipdu.set(self.ipdu.backbonefr.VddmBackBoneFr16, 'ChrgnOrDisChrgnStsFb', 0)#结束充电
        sleep(1)
        ENDtime1 = self.partner.send_request_and_return_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetChargingInfo", {},timeout=2)["out"][
            'recentChargeEndTime']
        ENDtime2 = self.partner.send_request_and_return_resp(TIMEMANANGEMENT_SERVICE_CLIENT, "GetVehicleTimeInfo", {},timeout=2)["out"][
            'UTCTime']
        C = time.strftime("%H%M%S", time.localtime(int(ENDtime1 / 1000)))
        RealENDtime1 = int(C)
        RealENDtime = (ENDtime2 + 80000000) // 1000
        RealENDtime2 = RealENDtime % 240000
        logger.info(f"{RealENDtime1}和{RealENDtime2}进行比较")
        assert abs(RealENDtime1*0.01 - RealENDtime2*0.01) < 0.5
        sleep(2)
