            self.ipdu.check(self.ipdu.chassiscan1.BgmChas1Fr08, 'CrpVehSpdSet', 7, timeout=0.5) # 蠕行车速
            self.partner.ck_no_event_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "EPedalConfig",  {"out": 0})    
            
