    @pytest.mark.full
    def test_caseid_1989190(self): # BGM上电后第一次调用set接口的参数值和记忆值一致
        self.set_gear_level_EnergyRecoveryCmd(gear="GearR", level=3, config=1)
        self.ipdu.set(self.ipdu.propulsioncan.EcmPropFr24, 'GearLvrIndcn', random.choice([0, 2])) # P/N档
        sleep(2)
        self.ipdu.pause_bus_send("propulsioncan")
        sleep(3)
        self.restart_bgm_and_connect_service(HIGHVOLTAGE_SERVICE_CLIENT, pause_all_bus=False, resume_all_bus=False)
        # 加载记忆值时需要上报event   
