        for X in [0, 1, 2, 4, 5]:
            self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr15, 'DCChrgnHndlSts', X)
            logger.info(f"充电枪状态_DCChrgnHndlSts={X}")
            self.ipdu.set(self.ipdu.propulsioncan.EcmPropFr04, 'DispHvBattLvlOfChrg', 10.0)
            self.partner.empty_all(0.2)
            for key,value in info1.items():
                self.ipdu.set(self.ipdu.propulsioncan.EcmPropFr04, 'DispHvBattLvlOfChrg', key)
                sleep(2)
                self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "HVSOCInfo", {'info': {'displaySoc': value}})
                self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetHVSOCInfo", {},
                                                  {'out': {'displaySoc': value}})
                self.partner.empty_all()
        self.ipdu.set(self.ipdu.propulsioncan.EcmPropFr04, 'DispHvBattLvlOfChrg', 100.0)
        sleep(0.1)
        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetHVSOCInfo", {},
                                                  {'out': {'displaySoc': 100.0}})
        #充电枪从不带电连接到带电连接时
        for Y in [0, 1, 2, 4, 5]:
            self.ipdu.set(self.ipdu.propulsioncan.EcmPropFr04, 'DispHvBattLvlOfChrg', 0.0)
            self.partner.empty_all(2)
            self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr15, 'DCChrgnHndlSts', Y)
            sleep(0.5)
            logger.info(f"充电枪连接状态_DCChrgnHndlSts={Y}")
            self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr15, 'DCChrgnHndlSts', 3)
            sleep(0.2)
            self.ipdu.set(self.ipdu.propulsioncan.EcmPropFr04, 'DispHvBattLvlOfChrg', 0.4)
            sleep(0.2)
            self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetHVSOCInfo", {},
                                                  {'out': {'displaySoc': 0.0}})
            self.ipdu.set(self.ipdu.propulsioncan.EcmPropFr04, 'DispHvBattLvlOfChrg', 0.5)
            sleep(0.2)
            self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "HVSOCInfo", {'info': {'displaySoc': 0.0}})
            self.ipdu.set(self.ipdu.propulsioncan.EcmPropFr04, 'DispHvBattLvlOfChrg', 1.5)
            sleep(0.2)
            self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetHVSOCInfo", {},
                                                  {'out': {'displaySoc': 1.0}})
            self.ipdu.set(self.ipdu.propulsioncan.EcmPropFr04, 'DispHvBattLvlOfChrg', 99.5)
            sleep(0.2)
            self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "HVSOCInfo", {'info': {'displaySoc': 99.0}})
        self.ipdu.set(self.ipdu.propulsioncan.EcmPropFr04, 'DispHvBattLvlOfChrg', 100.0)
        sleep(0.1)
        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetHVSOCInfo", {},
                                                  {'out': {'displaySoc': 100.0}})
        #充电枪从带电连接到不带电连接
