    @allure.title("插枪自动补电_充电枪未连接清除记忆值")
    @pytest.mark.sanity
    def test_caseid_1918694(self):
        self.sd_tester.change_usage_mode(2)
        def return_results(DispHvBattLvlOfChrg):
            if DispHvBattLvlOfChrg == 90.0:
                return 85.0
            if DispHvBattLvlOfChrg == 100.0:
                return 95.0
        for DispHvBattLvlOfChrg1 in [90.0, 100.0]:
            self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr15, 'DCChrgnHndlSts', 0)
