                self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetDischargingInfo", {},
                                                            {"out":{"isConnect":True,"acdcType":2}},timeout=2)
                self.partner.empty_all()
                logger.info(f"枪状态从{state1}切换到{state2}")
                self.ipdu.set(self.ipdu.propulsioncan.CddObcPropFr01, 'OnBdChrgrHndlSts1', state2)  
                sleep(1)
                self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT,"DischargingInfo",{"info":{"isConnect":False,"acdcType":0}})
