        self.ck_CLTCRangeIncrease_estimatedRangeIncrease_GetResponse(self.CltcKm(660,50,50),300,0,0)
        self.ipdu.set(self.ipdu.backbonefr.VddmBackBoneFr16, 'ChrgnOrDisChrgnStsFb', 15)
        sleep(0.5)
        self.ipdu.set(self.ipdu.propulsioncan.EcmPropFr04, 'DispHvBattLvlOfChrg', 60.0)
        sleep(0.5)
        self.partner.send_method_request(HIGHVOLTAGE_SERVICE_CLIENT, "SetRange",
                                            {"infos": {"type": 1, "CLTCRange": 400, "estimatedRange": 400}})
        sleep(1)
        self.ck_CLTCRangeIncrease_estimatedRangeIncrease_GetResponse(self.CltcKm(660,60,50),400,self.CltcKm(660,60,50)-self.CltcKm(660,50,50),100)
        self.partner.empty_all()
        self.ipdu.set(self.ipdu.backbonefr.VddmBackBoneFr16, 'ChrgnOrDisChrgnStsFb', 0)
        sleep(0.5)
