    @allure.title("通知和获取充电桩信息_交流CCP_插枪后赋值chargePowerInput & actualCurrent & chargeVoltageInput")
    @pytest.mark.full
    def test_caseid_1989492(self):
        self.ipdu.set(self.ipdu.propulsioncan.CddObcPropFr01, 'OnBdChrgrHndlSts1', 0)    
        self.restart_bgm_and_connect_service(HIGHVOLTAGE_SERVICE_CLIENT, pause_all_bus=True, resume_all_bus=False)
        self.ipdu.resume_send_pdu("propulsioncan",0x218)
        self.partner.empty_all(1)
        self.ipdu.set(self.ipdu.propulsioncan.CddObcPropFr01, 'OnBdChrgrHndlSts1', 1)     #仅恢复交流,不能发出event
        sleep(0.5)
        self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "NotifyChargingEquipmentInformation",
                                {"info": {"actualCurrent": 65535,"chargeVoltageInput": -1,"chargePowerInput": -1}})
        self.ipdu.set(self.ipdu.propulsioncan.CddObcPropFr01, 'OnBdChrgrHndlSts1', 0)    
        sleep(1)
        self.ipdu.resume_all_bus_send()
        self.partner.empty_all(2)
        self.ipdu.set(self.ipdu.propulsioncan.CddObcPropFr03, 'OnBdChrgrUAct', 0.0)
        sleep(0.5)
        self.ipdu.set(self.ipdu.propulsioncan.CddObcPropFr02, 'OnBdChrgrIAct', 0.0)
        sleep(0.5)
        self.partner.empty_all(1)
