        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetChargingInfo", {},
                                                            {"out":{"pluggerStatus":6}},timeout=2)
        self.partner.empty_all(4)#防止开机无脑上报一个event
        self.ipdu.resume_send_pdu("propulsioncan",0x218) #仅恢复交流,不能发出event
        self.ipdu.set(self.ipdu.propulsioncan.CddObcPropFr01, 'OnBdChrgrHndlSts1', 0)#这里框架会把直流的信号0带出来导致以下报错  
