    @allure.title("获取和通知充电信息_非直流时_遍历参数acdcType")
    @pytest.mark.smoke
    def test_caseid_1987721(self):
        self.ipdu.set(self.ipdu.propulsioncan.CddObcPropFr01, 'OnBdChrgrHndlSts1', 0)        
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr15, 'DCChrgnHndlSts', 0)
        sleep(1)
        self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetChargingInfo", {},
                                                            {"out":{"acdcType":0}},timeout=2)
        for DCSTS in range(1,6):
            for onbdsts in [0,8]:
                logger.info(f"发送直流枪信号{DCSTS}交流枪信号={onbdsts}")
                self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr15, 'DCChrgnHndlSts', DCSTS)
                sleep(1)
                self.ipdu.set(self.ipdu.propulsioncan.CddObcPropFr01, 'OnBdChrgrHndlSts1', onbdsts)    
                sleep(1)
                if onbdsts==8:
                    self.partner.ck_no_event(HIGHVOLTAGE_SERVICE_CLIENT,"ChargingInfo")
                else:
                    self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT,"ChargingInfo",{"info":{"isConnect":True,"acdcType":1}})
                    self.partner.send_request_and_ck_resp(HIGHVOLTAGE_SERVICE_CLIENT, "GetChargingInfo", {},
                                                                {"out":{"isConnect":True,"acdcType":1}},timeout=2)
                self.partner.empty_all()  
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr15, 'DCChrgnHndlSts', 0)
        sleep(1)
        for onbdsts1 in [1,2,3,5,7,9,10]: #信号发4时存在bug SOA-26752
            logger.info(f"交流枪信号={onbdsts1}")
            self.ipdu.set(self.ipdu.propulsioncan.CddObcPropFr01, 'OnBdChrgrHndlSts1', onbdsts1)    
