        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr11, 'DCChrgnPosPortT', 100.0)
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr11, 'DCChrgnNegPortT', 119.0)
