        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr11, 'DCChrgnNegPortT', 215.0)
        self.ipdu.set(self.ipdu.propulsioncan.HvcmPropFr01, 'OnBdChrgrPortT', 215.0)
