    @allure.title("通知和获取高压电池SOC状态_交直流CCP下只发直流信号仍然满足直流逻辑")
    @pytest.mark.full
    def test_caseid_1988091(self):
        self.ipdu.set(self.ipdu.propulsioncan.EcmPropFr04, 'DispHvBattLvlOfChrg', 89.8)
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr15, 'DCChrgnHndlSts', 0)
        self.ipdu.set(self.ipdu.propulsioncan.CddObcPropFr01, 'OnBdChrgrHndlSts1', 0) 
        self.partner.empty_all(1)
        self.ipdu.set(self.ipdu.propulsioncan.EcmPropFr04, 'DispHvBattLvlOfChrg', 86.5)
        self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "HVSOCInfo", {"info":{"displaySoc":87}}) #四舍五入
        self.ipdu.set(self.ipdu.propulsioncan.BecmPropFr15, 'DCChrgnHndlSts', 3)
        self.partner.empty_all(1)
        self.ipdu.set(self.ipdu.propulsioncan.EcmPropFr04, 'DispHvBattLvlOfChrg', 86.8)
        self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "HVSOCInfo", {"info":{"displaySoc":87}}) #四舍五入
        self.partner.empty_all(1)
        self.ipdu.set(self.ipdu.propulsioncan.EcmPropFr04, 'DispHvBattLvlOfChrg', 87.0)
        self.partner.empty_all(2)
        self.ipdu.set(self.ipdu.propulsioncan.EcmPropFr04, 'DispHvBattLvlOfChrg', 87.5) #2。1有bug
        sleep(1)
        self.partner.ck_s2s_event(HIGHVOLTAGE_SERVICE_CLIENT, "HVSOCInfo", {"info":{"displaySoc":87}})
        self.ipdu.set(self.ipdu.propulsioncan.EcmPropFr04, 'DispHvBattLvlOfChrg', 99.8)
