globalvar_publishID=1 # 1825472715239362561
@allure.feature("SOA服务接口")
@pytest.mark.tcam
@allure.story("架构基础/HighVoltageService")
class TestHighVoltageService_v2t(TestBase):
    def before_class(self, ecu):
        """测试用例的前处理"""
        super().before_class(self, ecu)
        self.tcam = TCAM_SSH()
        # 启动partner operator
        self.partner = S2sBaseClass([("CarConfigService", "client"),
                                     ("ChassisService", "client"),
                                     ("ConfigMasterService", "client")])
        self.partner.method_default_timeout = 3   
        self.sd_tester.tester_present() 
        self.ipdu.set(self.ipdu.backbonefr.BcmVddmBackBoneFr00, 'VehMtnStVehMtnSt', 'VehMtnSt2_StandStillVal3')
        self.ipdu.set(self.ipdu.backbonefr.VddmBackBoneFr18, 'TrsmParkLockdTrsmParkLockd', 'TrsmParkLock1_ParkNotEngd')
        self.ipdu.set(self.ipdu.backbonefr.VddmBackBoneFr03, 'GearLvrIndcn', 'GearLvrIndcn2_ParkIndcn')
        self.ipdu.set(self.ipdu.propulsioncan.EcmPropFr24, 'GearLvrIndcn', 0)
        self.ipdu.set(self.ipdu.propulsioncan.EcmPropComFr10, 'TrsmParkLockdTrsmParkLockd', 0)
        self.ipdu.set_vehspd(0)
        sleep(1)
        self.sd_tester.change_usage_mode(1)
        self.sd_tester.change_car_mode(0)
        self.sd_tester.write_single_ccp(566, 23) # 75度电池
        sleep(2)
        # 开启tcam的v2t模拟器
        self.bgmcli.type_commands("rm -rf /data/persistent/config_service/* ;rm -rf /data/persistent/config_master/*; rm -rf /data/config_service/s2s/*;")
        self.bgmcli.type_commands("sleep 3; cat /sys/power/sys_resumed; /app/bin/swdl -nw 10 1; sleep 5; shutdown -r") # 更改为冷启动
        # self.bgmcli.type_commands("rm -rf /data/persistent/config_service/* ;rm -rf /data/persistent/config_master/*; rm -rf /data/config_service/s2s/*;sleep 30; shutdown -r") # 删除数据库，因为配置文件序号是依次增大的，但是模拟器生成的是随机的
        self.tcam.type_commands("mv /mnt/sdcard/jiduEM.sh /oemdata/bin/ ;sleep 1;")
        self.tcam.type_commands("reboot")
        time.sleep(300) # 等tcam起来
        self.tcam.type_commands("ps -ef|grep v2t", output=True)
        self.bgmcli.type_commands("cat /sys/power/sys_resumed")# 查看启动方式
        # 为了防止诊断反馈NRC22,需要发送FlexRay报文
        self.ipdu.set(self.ipdu.backbonefr.BcmVddmBackBoneFr00, 'VehMtnStVehMtnSt', 'VehMtnSt2_StandStillVal3')
        global globalvar_publishID
        publishid=0
        logger.info(f"获取partner的所有event")
        for event in list(self.partner.partner_infos["ConfigMasterService_client"].event_queue.queue):
            logger.info(f"event={event}")
            if event['function'] == "UpdateConfigDataNotifyEvent":
                raw_data = eval(event['args'])
                logger.info(f"打印当前返回值: UpdateConfigDataNotifyEvent={raw_data}")
                ecuName=raw_data["ecuName"]
                configFileName=raw_data["info"]["fileInfoList"][0]["configFileName"]
                logger.info(f"打印当前返回值: ecuName={ecuName}, configFileName={configFileName}")
                if raw_data["ecuName"] == "BGM" and raw_data["info"]["fileInfoList"][0]["configFileName"] == "cloud_highvoltage":
                    publishid=raw_data["info"]["fileInfoList"][0]["publishID"]
                    globalvar_publishID=max(publishid, globalvar_publishID)
                    logger.info(f"打印当前返回值: publishid={publishid}, globalvar_publishID={globalvar_publishID}")
        sleep(5)         

    def after_class(self, ecu):
        """测试用例全部完成后的后处理"""
        self.partner.stop_operators()
        self.sd_tester.stop_tester_present()
        # 恢复tcam环境
        while True:
            self.tcam.type_commands("mv /oemdata/bin/jiduEM.sh /mnt/sdcard/")
            data = self.tcam.type_commands("ls /oemdata/bin/")
            if "jiduEM.sh" not in data:
                logger.info("配置文件清除成功")
                self.tcam.type_commands("reboot")
                break
            else:
                time.sleep(2)
                logger.info("等待清除配置文件")
        time.sleep(180)
        super().after_class(self, ecu)

